// Package embed 建立文字向量化函式，統一對接 OpenAI 相容端點、本地 Ollama 與離線備援。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 讓向量資料庫與 service 不綁定特定 embedding 供應商，僅依 config 切換
package embed

import (
	"fmt"
	"strings"

	"github.com/philippgille/chromem-go"
)

// Func 為單筆文字 → 正規化向量的函式型別，與 chromem-go 共用。
type Func = chromem.EmbeddingFunc

// Config 描述 embedding 供應者；金鑰與網址應由環境變數注入，不得寫死。
type Config struct {
	Provider string // openai | ollama | lexical
	BaseURL  string
	APIKey   string
	Model    string
}

const (
	// ProviderOpenAI 為任何 OpenAI 相容的 /v1/embeddings 端點。
	ProviderOpenAI = "openai"
	// ProviderOllama 為本地 Ollama 原生 embeddings API。
	ProviderOllama = "ollama"
	// ProviderLexical 為離線字元 n-gram 雜湊向量，僅供測試或無模型環境。
	ProviderLexical = "lexical"

	defaultOpenAIBaseURL = "https://api.openai.com/v1"
	defaultOpenAIModel   = "text-embedding-3-small"
	defaultOllamaModel   = "bge-m3"
)

// New 依設定建立向量化函式，並回傳可記錄於索引 metadata 的描述字串（provider/model）。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 索引必須記住建立時的 provider/model，查詢時用不同模型會得到無意義的相似度
// @ai:input cfg 供應者設定
// @ai:output 向量化函式、描述字串、錯誤
// @ai:sideeffect none（實際呼叫在函式執行時才發生）
func New(cfg Config) (Func, string, error) {
	provider := strings.ToLower(strings.TrimSpace(cfg.Provider))
	switch provider {
	case ProviderOpenAI:
		if cfg.APIKey == "" && (cfg.BaseURL == "" || strings.Contains(cfg.BaseURL, "api.openai.com")) {
			return nil, "", fmt.Errorf("embedding provider %q requires api_key", provider)
		}
		baseURL := cfg.BaseURL
		if baseURL == "" {
			baseURL = defaultOpenAIBaseURL
		}
		model := cfg.Model
		if model == "" {
			model = defaultOpenAIModel
		}
		// normalized=nil：chromem 於第一次請求自動偵測向量是否已正規化。
		return chromem.NewEmbeddingFuncOpenAICompat(baseURL, cfg.APIKey, model, nil), provider + "/" + model, nil
	case ProviderOllama:
		model := cfg.Model
		if model == "" {
			model = defaultOllamaModel
		}
		return chromem.NewEmbeddingFuncOllama(model, cfg.BaseURL), provider + "/" + model, nil
	case ProviderLexical, "":
		return NewLexical(DefaultLexicalDims), ProviderLexical + "/ngram-" + fmt.Sprint(DefaultLexicalDims), nil
	default:
		return nil, "", fmt.Errorf("unknown embedding provider %q", cfg.Provider)
	}
}
